import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        System.out.println(rataRata(Arrays.asList(70, 80, 90)));
        System.out.println(rataRata(Arrays.asList(2.5, 3.5)));
    }

    static double rataRata(List<? extends Number> angka) {
        double total = 0;
        for (Number n : angka) {
            total += n.doubleValue();
        }
        return total / angka.size();
    }
}

